#define SPEECH_CLIP_COUNT  28

// ── Lookup by name (returns NULL if not found) ─────────────
static inline const SpeechClip *speech_find(const char *name) {
    for (int i = 0; i < SPEECH_CLIP_COUNT; i++)
        if (strcmp(_ALL_CLIPS[i].name, name) == 0)
            return &_ALL_CLIPS[i];
    return (void*)0;
}

